import{_ as n,a as o,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 单元 4 语法总结","description":"L73–L96 规则、例句、易错点。","frontmatter":{"title":"第一册：英语初阶 · 单元 4 语法总结","description":"L73–L96 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L73–L96 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 4：过去事件、完成结果与未来安排","link":"/life/english/new-concept/book-1/unit-04/overview"},"next":{"text":"第一册：英语初阶 · 单元 4 单词与短语","link":"/life/english/new-concept/book-1/unit-04/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 4：过去事件、完成结果与未来安排","link":"/life/english/new-concept/book-1/unit-04/overview"},"next":{"text":"第一册：英语初阶 · 单元 4 单词与短语","link":"/life/english/new-concept/book-1/unit-04/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/grammar.md","filePath":"life/english/new-concept/book-1/unit-04/grammar.md"}'),s={name:"life/english/new-concept/book-1/unit-04/grammar.md"};function r(i,e,l,h,p,g){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-单元-4-语法总结" tabindex="-1">第一册：英语初阶 · 单元 4 语法总结 <a class="header-anchor" href="#第一册-英语初阶-·-单元-4-语法总结" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 4 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元复习与自测</a></p><h2 id="不规则过去式" tabindex="-1">不规则过去式 <a class="header-anchor" href="#不规则过去式" aria-label="Permalink to &quot;不规则过去式&quot;">​</a></h2><p>部分高频动词的过去式不是加 ed：go→went、see→saw、say→said、take→took。肯定句使用过去式，问句和否定句中 did 后恢复原形。复述路线可以按先后顺序组织动作，但 next、then 等顺序词不自动决定时态；应先确认整个故事发生在过去。人名变化不会改变过去式形式。</p><p><strong>L73 原创例句：</strong> We took the wrong bus and went to the harbour.</p><p>我们坐错了公交车，去了港口。</p><p><strong>L74 原创例句：</strong> Did the guard show you the right road?</p><p>警卫给你指了正确的路吗？</p><p><strong>易错：</strong> did 后用 show 而非 showed；went 只放在没有 did 的过去肯定句中。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-073">Lesson 73</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-074">Lesson 74</a></p><h2 id="过去时间标记与-buy-bought" tabindex="-1">过去时间标记与 buy/bought <a class="header-anchor" href="#过去时间标记与-buy-bought" aria-label="Permalink to &quot;过去时间标记与 buy/bought&quot;">​</a></h2><p>明确结束的过去时间如 last month、two days ago，通常与一般过去时配合。buy 的过去式为 bought，wear 的过去式为 wore。ago 表从现在向前推多少时间，放在数量短语之后。询问过去购买用 Did you buy ...?，不能在 did 后保留 bought。大小合适与舒适是不同属性，描述时可分别说明。</p><p><strong>L75 原创例句：</strong> I bought these boots three weeks ago.</p><p>我三周前买了这双靴子。</p><p><strong>L76 原创例句：</strong> Did you wear the new shoes yesterday?</p><p>你昨天穿了新鞋吗？</p><p><strong>易错：</strong> two weeks ago 前一般不加 in；ago 放在时间长度之后。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-075">Lesson 75</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-076">Lesson 76</a></p><h2 id="时间介词与否定疑问句" tabindex="-1">时间介词与否定疑问句 <a class="header-anchor" href="#时间介词与否定疑问句" aria-label="Permalink to &quot;时间介词与否定疑问句&quot;">​</a></h2><p>预约时 at + 钟点，on + 某日，in + 月份或年份。否定疑问句如 Can&#39;t you come earlier? 常带有期待或惊讶，不是完全中性的询问。回答 Yes, I can 表能，No, I can&#39;t 表不能，按实际情况回答，不按中文句首“是/不是”机械翻译。本页训练预约表达，不提供牙科处理建议。</p><p><strong>L77 原创例句：</strong> My appointment is at ten on Thursday.</p><p>我的预约在星期四十点。</p><p><strong>L78 原创例句：</strong> Can you come earlier on Friday?</p><p>你星期五能早点来吗？</p><p><strong>易错：</strong> on Friday morning 而不是 in Friday morning；at 只标钟点，不接整日。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-077">Lesson 77</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-078">Lesson 78</a></p><h2 id="need-与-must" tabindex="-1">need 与 must <a class="header-anchor" href="#need-与-must" aria-label="Permalink to &quot;need 与 must&quot;">​</a></h2><p>need 作实义动词时，可接名词或 to do：need some rice、need to buy rice。第三人称用 needs，否定借助 don&#39;t/doesn&#39;t。must 是情态动词，直接加原形，不加 to。needn&#39;t 是“不必”，其后直接接动词原形。学习时先确定用的是实义动词 need 还是情态表达，避免混用句式。</p><p><strong>L79 原创例句：</strong> We need to buy rice and tomatoes.</p><p>我们需要买米和西红柿。</p><p><strong>L80 原创例句：</strong> She must go to the pharmacy before six.</p><p>她必须六点前去药店。</p><p><strong>易错：</strong> need to go 与 must go 的结构不同；不要写 must to go。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-079">Lesson 79</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-080">Lesson 80</a></p><h2 id="have-had-的活动用法" tabindex="-1">have/had 的活动用法 <a class="header-anchor" href="#have-had-的活动用法" aria-label="Permalink to &quot;have/had 的活动用法&quot;">​</a></h2><p>have 不只表示拥有，也可与 meal、bath、rest 等组成活动短语。have lunch 表吃午饭，have a rest 表休息。一般过去时用 had，问句中 did 后仍用 have。三餐名词单独表示吃饭时常不加冠词，但有修饰语时可说 a good lunch；不能把所有 have + 名词都直译成“拥有”。</p><p><strong>L81 原创例句：</strong> We had vegetable soup for lunch.</p><p>我们午饭喝了蔬菜汤。</p><p><strong>L82 原创例句：</strong> Did you have a good rest after the journey?</p><p>旅途结束后你休息得好吗？</p><p><strong>易错：</strong> did 后用 have，而不是 had；have a rest 中 rest 为可数用法。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-081">Lesson 81</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-082">Lesson 82</a></p><h2 id="现在完成时入门" tabindex="-1">现在完成时入门 <a class="header-anchor" href="#现在完成时入门" aria-label="Permalink to &quot;现在完成时入门&quot;">​</a></h2><p>现在完成时由 have/has + 过去分词构成，常把过去完成的动作与现在结果联系起来。already 常用于肯定句，yet 常用于疑问或否定句末。问句将 have/has 提前。pack→packed 是规则变化；have 的过去分词是 had，所以 Have you had lunch? 中两个 have 作用不同。不要省略助动词。</p><p><strong>L83 原创例句：</strong> I have already packed my suitcase.</p><p>我已经收拾好手提箱了。</p><p><strong>L84 原创例句：</strong> Have you checked the train times yet?</p><p>你查过火车时刻了吗？</p><p><strong>易错：</strong> 现在完成时需要 have/has；I already packed 在本课目标结构中应补 have。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-083">Lesson 83</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-084">Lesson 84</a></p><h2 id="have-been-to-与过去时间" tabindex="-1">have been to 与过去时间 <a class="header-anchor" href="#have-been-to-与过去时间" aria-label="Permalink to &quot;have been to 与过去时间&quot;">​</a></h2><p>have been to 表示去过并已返回的经历；have gone to 通常表示去了且尚未返回。谈经验可用现在完成时，补充明确结束的日期或年份时通常改一般过去时。I have been to Rome 与 I went there in 2022 可在一段话中衔接。不能把现在完成时直接与 yesterday 等已结束时间机械拼接。</p><p><strong>L85 原创例句：</strong> I have been to Vienna twice.</p><p>我去过维也纳两次。</p><p><strong>L86 原创例句：</strong> Rita has gone to the bank and will be back soon.</p><p>丽塔去银行了，很快就回来。</p><p><strong>易错：</strong> 谈仍未回来的人用 has gone；不要把 gone 和 been 都译为无差别的“去过”。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-085">Lesson 85</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-086">Lesson 86</a></p><h2 id="现在完成时的疑问与否定" tabindex="-1">现在完成时的疑问与否定 <a class="header-anchor" href="#现在完成时的疑问与否定" aria-label="Permalink to &quot;现在完成时的疑问与否定&quot;">​</a></h2><p>have/has + 过去分词表达已完成并影响现在的动作。yet 在疑问句中常译“已经”，在否定句中常译“还”。repair→repaired，break→broken；不规则过去分词不能一律加 ed。Has the mechanic repaired it? 与 He hasn&#39;t repaired it yet 对应。描述事故时先区分已经发生的事件与现在的修理状态。</p><p><strong>L87 原创例句：</strong> The mechanic has not repaired my bicycle yet.</p><p>修理工还没修好我的自行车。</p><p><strong>L88 原创例句：</strong> Have they replaced the broken window yet?</p><p>他们换好破窗户了吗？</p><p><strong>易错：</strong> yet 在这里常位于句末；has 后不能直接跟 repair 原形。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-087">Lesson 87</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-088">Lesson 88</a></p><h2 id="since-与-for" tabindex="-1">since 与 for <a class="header-anchor" href="#since-与-for" aria-label="Permalink to &quot;since 与 for&quot;">​</a></h2><p>现在完成时可以描述从过去延续到现在的状态。for 后接时长，如 for six years；since 后接起点，如 since 2020 或 since I moved here。问持续多久用 How long have you ...?。并非所有动词都能直接接持续时长：买到某物是瞬间事件，表达已拥有多久常用 have had，而不直接说 have bought for。</p><p><strong>L89 原创例句：</strong> We have lived here for six years.</p><p>我们已经在这里住了六年。</p><p><strong>L90 原创例句：</strong> She has owned this flat since 2020.</p><p>她从2020年起就拥有这套公寓。</p><p><strong>易错：</strong> since 后不是 six years 这种时长；for six years 与 since 2020 不要混淆。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-089">Lesson 89</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-090">Lesson 90</a></p><h2 id="will-表将来" tabindex="-1">will 表将来 <a class="header-anchor" href="#will-表将来" aria-label="Permalink to &quot;will 表将来&quot;">​</a></h2><p>will + 动词原形表示未来情况、预测或说话时的决定，所有人称形式相同。否定 will not 缩写为 won&#39;t；疑问把 will 提前。will be 后可接形容词或地点，但 will 后不能直接跟形容词而漏 be。与 be going to 相比，will 常用来作临时决定或一般预测，但两者并非机械互斥。</p><p><strong>L91 原创例句：</strong> Our neighbours will move next month.</p><p>我们的邻居下个月将搬家。</p><p><strong>L92 原创例句：</strong> Will the new room be ready tomorrow?</p><p>新房间明天会准备好吗？</p><p><strong>易错：</strong> will 后接原形；will ready 缺少 be，不能直接跟形容词。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-091">Lesson 91</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-092">Lesson 92</a></p><h2 id="过去、现在与将来的时间线" tabindex="-1">过去、现在与将来的时间线 <a class="header-anchor" href="#过去、现在与将来的时间线" aria-label="Permalink to &quot;过去、现在与将来的时间线&quot;">​</a></h2><p>先确定时间再选动词形式：过去 go→went，未来 will go，现在习惯 go/goes。问过去用 did + 原形，问未来用 will + 原形。tomorrow、last year 等时间词提供线索，但要结合整个叙述。多句对比中，人称变化和时态变化是两个独立检查项，不能只改时间词而保留错误谓语。</p><p><strong>L93 原创例句：</strong> Our neighbour flew to Madrid last week.</p><p>我们的邻居上周飞去了马德里。</p><p><strong>L94 原创例句：</strong> He will return next Tuesday.</p><p>他将在下周二回来。</p><p><strong>易错：</strong> did 和 will 后都接原形，但表达的时间不同；不能把 Did he go tomorrow? 当正常将来问句。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-093">Lesson 93</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-094">Lesson 94</a></p><h2 id="had-better-与时间表达" tabindex="-1">had better 与时间表达 <a class="header-anchor" href="#had-better-与时间表达" aria-label="Permalink to &quot;had better 与时间表达&quot;">​</a></h2><p>had better + 动词原形表示在当前情境下最好做某事，常带不这样做会有后果的意味。虽然含 had，整体不表示过去；否定为 had better not + 原形。时间可用直接读法 ten twenty，或 twenty past ten。问确切发车时间时要明确日期与上午下午，避免只说含糊钟点。</p><p><strong>L95 原创例句：</strong> We had better leave before the traffic gets heavy.</p><p>我们最好在交通拥堵前出发。</p><p><strong>L96 原创例句：</strong> You had better not miss the last train.</p><p>你最好不要错过末班车。</p><p><strong>易错：</strong> had better 后不加 to；否定 not 放在 better 后，而不是用 don&#39;t。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-095">Lesson 95</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-096">Lesson 96</a></p>',98)])])}const u=n(s,[["render",r]]);export{d as __pageData,u as default};
